<?php
require 'config.php';header('Content-Type: application/json');$courtId=(int)($_GET['court_id']??0);$date=$_GET['date']??'';if($courtId<1||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date<date('Y-m-d')){http_response_code(400);echo json_encode(['error'=>'Invalid court or date']);exit;}$slots=$conn->query('SELECT id,start_time,end_time FROM time_slots ORDER BY start_time')->fetch_all(MYSQLI_ASSOC);$stmt=$conn->prepare("SELECT time_slot_id FROM bookings WHERE court_id=? AND booking_date=? AND status='confirmed'");$stmt->bind_param('is',$courtId,$date);$stmt->execute();$busy=array_map('intval',array_column($stmt->get_result()->fetch_all(MYSQLI_ASSOC),'time_slot_id'));$stmt=$conn->prepare('SELECT time_slot_id FROM closures WHERE court_id=? AND closure_date=?');$stmt->bind_param('is',$courtId,$date);$stmt->execute();$allDay=false;$closed=[];foreach($stmt->get_result() as $r){if($r['time_slot_id']===null)$allDay=true;else$closed[]=(int)$r['time_slot_id'];}$result=[];foreach($slots as $s){$available=strtotime($date.' '.$s['start_time'])>time()&&!$allDay&&!in_array((int)$s['id'],$busy,true)&&!in_array((int)$s['id'],$closed,true);$result[]=['id'=>(int)$s['id'],'label'=>date('g:i A',strtotime($s['start_time'])).' - '.date('g:i A',strtotime($s['end_time'])),'available'=>$available];}echo json_encode($result);
